using System.Diagnostics;
using TextAnalysis;

const string SampleText =
    "The quick brown fox jumps over the lazy dog. " +
    "A journey of a thousand miles begins with a single step. " +
    "To be or not to be that is the question. " +
    "All that glitters is not gold. " +
    "The early bird catches the worm and the late bird misses it entirely.";

var analyzer = new TextAnalyzer(SampleText);

const int warmupIterations = 1000;
const int benchIterations = 100_000;

// Warmup
for (int i = 0; i < warmupIterations; i++)
{
    analyzer.AverageWordLength();
    analyzer.WordLengthHistogram();
    analyzer.UniqueWordCount();
}

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Iterations: {benchIterations:N0}");
Console.WriteLine();

// Benchmark AverageWordLength
var sw = Stopwatch.StartNew();
for (int i = 0; i < benchIterations; i++)
    analyzer.AverageWordLength();
sw.Stop();
Console.WriteLine($"AverageWordLength:    {sw.Elapsed.TotalMilliseconds,8:F3} ms total | {sw.Elapsed.TotalNanoseconds / benchIterations,8:F1} ns/op");

// Benchmark WordLengthHistogram
sw.Restart();
for (int i = 0; i < benchIterations; i++)
    analyzer.WordLengthHistogram();
sw.Stop();
Console.WriteLine($"WordLengthHistogram:  {sw.Elapsed.TotalMilliseconds,8:F3} ms total | {sw.Elapsed.TotalNanoseconds / benchIterations,8:F1} ns/op");

// Benchmark UniqueWordCount
sw.Restart();
for (int i = 0; i < benchIterations; i++)
    analyzer.UniqueWordCount();
sw.Stop();
Console.WriteLine($"UniqueWordCount:      {sw.Elapsed.TotalMilliseconds,8:F3} ms total | {sw.Elapsed.TotalNanoseconds / benchIterations,8:F1} ns/op");

